#!/usr/bin/env python3
"""Claude review MCP server for Codex-first ARIS workflows.

This server exposes a narrow review-only interface over Claude Code CLI so
Codex can remain the executor while Claude acts as the external reviewer.
"""

from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
import time
import traceback
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


sys.stdout = os.fdopen(sys.stdout.fileno(), "wb", buffering=0)
sys.stdin = os.fdopen(sys.stdin.fileno(), "rb", buffering=0)

SERVER_NAME = os.environ.get("CLAUDE_REVIEW_SERVER_NAME", "claude-review")
CLAUDE_BIN = os.environ.get("CLAUDE_BIN", "claude")
DEFAULT_MODEL = os.environ.get("CLAUDE_REVIEW_MODEL", "")
DEFAULT_SYSTEM = os.environ.get("CLAUDE_REVIEW_SYSTEM", "")
DEFAULT_TOOLS = os.environ.get("CLAUDE_REVIEW_TOOLS", "")
DEFAULT_TIMEOUT_SEC = int(os.environ.get("CLAUDE_REVIEW_TIMEOUT_SEC", "600"))
DEBUG_LOG = Path(os.environ.get("CLAUDE_REVIEW_DEBUG_LOG", f"/tmp/{SERVER_NAME}-mcp-debug.log"))
STATE_DIR = Path(
    os.environ.get(
        "CLAUDE_REVIEW_STATE_DIR",
        str(Path.home() / ".codex" / "state" / SERVER_NAME),
    )
)
JOBS_DIR = STATE_DIR / "jobs"

_use_ndjson = False
TERMINAL_JOB_STATES = {"completed", "failed"}


def debug_log(message: str) -> None:
    try:
        DEBUG_LOG.parent.mkdir(parents=True, exist_ok=True)
        with DEBUG_LOG.open("a", encoding="utf-8") as fh:
            fh.write(f"{message}\n")
    except OSError:
        pass


def send_response(response: dict[str, Any]) -> None:
    global _use_ndjson

    payload = json.dumps(response, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    debug_log(f"SEND {payload.decode('utf-8', errors='replace')}")
    if _use_ndjson:
        sys.stdout.write(payload + b"\n")
    else:
        header = f"Content-Length: {len(payload)}\r\n\r\n".encode("utf-8")
        sys.stdout.write(header + payload)
    sys.stdout.flush()


def read_message() -> dict[str, Any] | None:
    global _use_ndjson

    line = sys.stdin.readline()
    if not line:
        return None

    line_text = line.decode("utf-8").rstrip("\r\n")
    if line_text.lower().startswith("content-length:"):
        try:
            content_length = int(line_text.split(":", 1)[1].strip())
        except ValueError:
            return None

        while True:
            header_line = sys.stdin.readline()
            if not header_line:
                return None
            if header_line in {b"\r\n", b"\n"}:
                break

        body = sys.stdin.read(content_length)
        try:
            return json.loads(body.decode("utf-8"))
        except json.JSONDecodeError:
            return None

    if line_text.startswith("{") or line_text.startswith("["):
        _use_ndjson = True
        try:
            return json.loads(line_text)
        except json.JSONDecodeError:
            return None

    return None


def find_claude_bin() -> str | None:
    if Path(CLAUDE_BIN).is_file():
        return CLAUDE_BIN
    return shutil.which(CLAUDE_BIN)


def parse_claude_json(raw_stdout: str) -> tuple[dict[str, Any] | None, str | None]:
    lines = [line.strip() for line in raw_stdout.splitlines() if line.strip()]
    if not lines:
        return None, "Claude CLI returned empty output"

    for candidate in reversed(lines):
        try:
            payload = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(payload, dict):
            return payload, None

    return None, "Claude CLI did not return JSON output"


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = path.with_suffix(path.suffix + ".tmp")
    temp_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    temp_path.replace(path)


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def job_state_path(job_id: str) -> Path:
    return JOBS_DIR / f"{job_id}.json"


def is_pid_alive(pid: int | None) -> bool:
    if not pid or pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True


def serialize_job(job: dict[str, Any]) -> dict[str, Any]:
    result = job.get("result") or {}
    return {
        "jobId": job.get("jobId"),
        "status": job.get("status"),
        "done": job.get("status") in TERMINAL_JOB_STATES,
        "threadId": result.get("threadId"),
        "response": result.get("response"),
        "model": result.get("model"),
        "duration_ms": result.get("duration_ms"),
        "stop_reason": result.get("stop_reason"),
        "error": job.get("error"),
        "createdAt": job.get("createdAt"),
        "startedAt": job.get("startedAt"),
        "completedAt": job.get("completedAt"),
        "updatedAt": job.get("updatedAt"),
        "resumeHint": "Call review_status with this jobId until done=true.",
    }


def build_command(
    prompt: str,
    *,
    session_id: str | None = None,
    model: str | None = None,
    system: str | None = None,
    tools: str | None = None,
) -> list[str]:
    bin_path = find_claude_bin()
    if not bin_path:
        raise FileNotFoundError(f"Claude CLI not found: {CLAUDE_BIN}")

    cmd = [bin_path, "-p", prompt, "--output-format", "json", "--permission-mode", "plan"]

    if session_id:
        cmd.extend(["--resume", session_id])

    selected_model = model or DEFAULT_MODEL
    if selected_model:
        cmd.extend(["--model", selected_model])

    selected_system = system or DEFAULT_SYSTEM
    if selected_system:
        cmd.extend(["--system-prompt", selected_system])

    selected_tools = DEFAULT_TOOLS if tools is None else tools
    cmd.extend(["--tools", selected_tools])
    return cmd


def run_claude_review(
    prompt: str,
    *,
    session_id: str | None = None,
    model: str | None = None,
    system: str | None = None,
    tools: str | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    try:
        cmd = build_command(
            prompt,
            session_id=session_id,
            model=model,
            system=system,
            tools=tools,
        )
    except FileNotFoundError as exc:
        return None, str(exc)

    debug_log(f"RUN {' '.join(cmd)}")
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            stdin=subprocess.DEVNULL,
            timeout=DEFAULT_TIMEOUT_SEC,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return None, f"Claude review timed out after {DEFAULT_TIMEOUT_SEC} seconds"

    payload, parse_error = parse_claude_json(result.stdout)
    if parse_error:
        stderr = result.stderr.strip()
        message = parse_error if not stderr else f"{parse_error}. stderr: {stderr}"
        return None, message

    assert payload is not None
    if result.returncode != 0 or payload.get("is_error"):
        message = str(payload.get("result") or payload.get("error") or result.stderr.strip() or "Claude review failed")
        return None, message

    thread_id = payload.get("session_id")
    response_text = str(payload.get("result", "")).strip()
    model_name = payload.get("model", "") or model or DEFAULT_MODEL
    return {
        "threadId": thread_id,
        "response": response_text,
        "model": model_name,
        "duration_ms": payload.get("duration_ms"),
        "stop_reason": payload.get("stop_reason"),
    }, None


def start_async_review(
    prompt: str,
    *,
    session_id: str | None = None,
    model: str | None = None,
    system: str | None = None,
    tools: str | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    job_id = uuid.uuid4().hex
    created_at = utc_now()
    job = {
        "jobId": job_id,
        "status": "queued",
        "createdAt": created_at,
        "startedAt": None,
        "completedAt": None,
        "updatedAt": created_at,
        "error": None,
        "result": None,
        "workerPid": None,
        "request": {
            "prompt": prompt,
            "threadId": session_id,
            "model": model,
            "system": system,
            "tools": tools,
        },
    }

    job_path = job_state_path(job_id)
    write_json(job_path, job)

    try:
        worker = subprocess.Popen(
            [sys.executable, str(Path(__file__).resolve()), "--run-job", job_id],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            close_fds=True,
            start_new_session=True,
        )
    except OSError as exc:
        job["status"] = "failed"
        job["completedAt"] = utc_now()
        job["updatedAt"] = job["completedAt"]
        job["error"] = f"Failed to launch background review worker: {exc}"
        write_json(job_path, job)
        return None, job["error"]

    job["workerPid"] = worker.pid
    job["updatedAt"] = utc_now()
    write_json(job_path, job)
    debug_log(f"JOB_START job_id={job_id} worker_pid={worker.pid}")
    return serialize_job(job), None


def get_review_status(job_id: str, *, wait_seconds: int = 0) -> tuple[dict[str, Any] | None, str | None]:
    job_path = job_state_path(job_id)
    if not job_path.exists():
        return None, f"Unknown jobId: {job_id}"

    deadline = time.monotonic() + max(wait_seconds, 0)
    while True:
        job = read_json(job_path)
        if job.get("status") in {"queued", "running"} and not is_pid_alive(job.get("workerPid")):
            job["status"] = "failed"
            job["error"] = "Background review worker exited before writing a final result"
            job["completedAt"] = utc_now()
            job["updatedAt"] = job["completedAt"]
            write_json(job_path, job)
        if job.get("status") in TERMINAL_JOB_STATES:
            return serialize_job(job), None
        if time.monotonic() >= deadline:
            return serialize_job(job), None
        time.sleep(min(0.5, max(deadline - time.monotonic(), 0.0)))


def run_async_job(job_id: str) -> int:
    job_path = job_state_path(job_id)
    if not job_path.exists():
        debug_log(f"JOB_MISSING job_id={job_id}")
        return 1

    job = read_json(job_path)
    job["status"] = "running"
    job["startedAt"] = utc_now()
    job["updatedAt"] = job["startedAt"]
    job["workerPid"] = os.getpid()
    write_json(job_path, job)
    debug_log(f"JOB_RUNNING job_id={job_id} worker_pid={os.getpid()}")

    request = job.get("request") or {}
    try:
        payload, error = run_claude_review(
            str(request.get("prompt", "")),
            session_id=request.get("threadId"),
            model=request.get("model"),
            system=request.get("system"),
            tools=request.get("tools"),
        )
    except Exception as exc:
        payload = None
        error = f"Background review crashed: {exc}"
        debug_log(traceback.format_exc())

    finished_at = utc_now()
    job = read_json(job_path)
    job["updatedAt"] = finished_at
    job["completedAt"] = finished_at
    if error:
        job["status"] = "failed"
        job["error"] = error
        job["result"] = None
        debug_log(f"JOB_FAILED job_id={job_id} error={error}")
        write_json(job_path, job)
        return 1

    job["status"] = "completed"
    job["error"] = None
    job["result"] = payload
    debug_log(f"JOB_COMPLETED job_id={job_id} thread_id={(payload or {}).get('threadId')}")
    write_json(job_path, job)
    return 0


def tool_success(request_id: Any, payload: dict[str, Any]) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "result": {
            "content": [{"type": "text", "text": json.dumps(payload, ensure_ascii=False)}],
        },
    }


def tool_error(request_id: Any, message: str) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "result": {
            "content": [{"type": "text", "text": json.dumps({"error": message}, ensure_ascii=False)}],
            "isError": True,
        },
    }


def handle_request(request: dict[str, Any]) -> dict[str, Any] | None:
    request_id = request.get("id")
    method = request.get("method", "")
    params = request.get("params", {})
    debug_log(f"REQUEST id={request_id!r} method={method} params={json.dumps(params, ensure_ascii=False)}")

    if request_id is None:
        if method in {"notifications/initialized", "initialized"}:
            return None
        return None

    if method == "initialize":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "protocolVersion": "2024-11-05",
                "capabilities": {"tools": {}},
                "serverInfo": {"name": SERVER_NAME, "version": "1.0.0"},
            },
        }

    if method == "ping":
        return {"jsonrpc": "2.0", "id": request_id, "result": {}}

    if method == "resources/list":
        return {"jsonrpc": "2.0", "id": request_id, "result": {"resources": []}}

    if method == "resources/templates/list":
        return {"jsonrpc": "2.0", "id": request_id, "result": {"resourceTemplates": []}}

    if method in {"notifications/initialized", "initialized"}:
        return {"jsonrpc": "2.0", "id": request_id, "result": {}}

    if method == "tools/list":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "tools": [
                    {
                        "name": "review",
                        "description": "Run a fresh Claude Code review and return JSON containing threadId and response.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "prompt": {"type": "string", "description": "Reviewer prompt"},
                                "system": {"type": "string", "description": "Optional system prompt"},
                                "model": {"type": "string", "description": "Optional Claude model override"},
                                "tools": {"type": "string", "description": "Optional Claude tools override, empty string disables tools"},
                            },
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_reply",
                        "description": "Continue a previous Claude Code review session using threadId/session_id.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "threadId": {"type": "string", "description": "Claude session id from a previous review call"},
                                "thread_id": {"type": "string", "description": "Alias of threadId"},
                                "prompt": {"type": "string", "description": "Follow-up reviewer prompt"},
                                "system": {"type": "string", "description": "Optional system prompt override"},
                                "model": {"type": "string", "description": "Optional Claude model override"},
                                "tools": {"type": "string", "description": "Optional Claude tools override, empty string disables tools"},
                            },
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_start",
                        "description": "Start a background Claude Code review job and return a resumable jobId immediately.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "prompt": {"type": "string", "description": "Reviewer prompt"},
                                "system": {"type": "string", "description": "Optional system prompt"},
                                "model": {"type": "string", "description": "Optional Claude model override"},
                                "tools": {"type": "string", "description": "Optional Claude tools override, empty string disables tools"},
                            },
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_reply_start",
                        "description": "Start a background follow-up review job in an existing Claude thread and return a resumable jobId immediately.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "threadId": {"type": "string", "description": "Claude session id from a previous review call"},
                                "thread_id": {"type": "string", "description": "Alias of threadId"},
                                "prompt": {"type": "string", "description": "Follow-up reviewer prompt"},
                                "system": {"type": "string", "description": "Optional system prompt override"},
                                "model": {"type": "string", "description": "Optional Claude model override"},
                                "tools": {"type": "string", "description": "Optional Claude tools override, empty string disables tools"},
                            },
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_status",
                        "description": "Check whether a background review job has finished and fetch the final result when available.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "jobId": {"type": "string", "description": "Background review job id"},
                                "job_id": {"type": "string", "description": "Alias of jobId"},
                                "waitSeconds": {"type": "integer", "description": "Optional bounded wait before returning status"},
                            },
                            "required": ["jobId"],
                        },
                    },
                ]
            },
        }

    if method == "tools/call":
        name = params.get("name", "")
        args = params.get("arguments", {}) or {}

        if name == "review":
            payload, error = run_claude_review(
                str(args.get("prompt", "")),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_reply":
            thread_id = args.get("threadId") or args.get("thread_id")
            if not thread_id:
                return tool_error(request_id, "threadId or thread_id is required")
            payload, error = run_claude_review(
                str(args.get("prompt", "")),
                session_id=str(thread_id),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_start":
            payload, error = start_async_review(
                str(args.get("prompt", "")),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_reply_start":
            thread_id = args.get("threadId") or args.get("thread_id")
            if not thread_id:
                return tool_error(request_id, "threadId or thread_id is required")
            payload, error = start_async_review(
                str(args.get("prompt", "")),
                session_id=str(thread_id),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_status":
            job_id = args.get("jobId") or args.get("job_id")
            if not job_id:
                return tool_error(request_id, "jobId or job_id is required")
            wait_seconds_raw = args.get("waitSeconds", 0)
            try:
                wait_seconds = int(wait_seconds_raw)
            except (TypeError, ValueError):
                return tool_error(request_id, "waitSeconds must be an integer")
            payload, error = get_review_status(str(job_id), wait_seconds=max(wait_seconds, 0))
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "error": {"code": -32601, "message": f"Unknown tool: {name}"},
        }

    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "error": {"code": -32601, "message": f"Unknown method: {method}"},
    }


def main() -> None:
    if len(sys.argv) == 3 and sys.argv[1] == "--run-job":
        raise SystemExit(run_async_job(sys.argv[2]))

    debug_log(f"=== {SERVER_NAME} starting ===")
    while True:
        try:
            request = read_message()
            if request is None:
                debug_log("EOF")
                break
            response = handle_request(request)
            if response is not None:
                send_response(response)
        except Exception:
            debug_log(traceback.format_exc())
            break


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Gemini review MCP server for Codex-first workflows.

This server mirrors the narrow review-only interface used by the existing
review bridges, but defaults to the direct Gemini API so Codex can reuse the
original ARIS review-heavy skill structure with minimal changes. Gemini CLI is
kept only as an optional fallback. It is intentionally self-contained so it can
be copied into `~/.codex/mcp-servers/gemini-review/` without depending on this
repository.
"""

from __future__ import annotations

import base64
import json
import mimetypes
import os
import shutil
import subprocess
import sys
import time
import traceback
import urllib.error
import urllib.request
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


sys.stdout = os.fdopen(sys.stdout.fileno(), "wb", buffering=0)
sys.stdin = os.fdopen(sys.stdin.fileno(), "rb", buffering=0)

SERVER_NAME = os.environ.get("GEMINI_REVIEW_SERVER_NAME", "gemini-review")
GEMINI_BIN = os.environ.get("GEMINI_BIN", "gemini")
DEFAULT_MODEL = os.environ.get("GEMINI_REVIEW_MODEL", "")
DEFAULT_SYSTEM = os.environ.get("GEMINI_REVIEW_SYSTEM", "")
DEFAULT_BACKEND = os.environ.get("GEMINI_REVIEW_BACKEND", "api")
DEFAULT_TIMEOUT_SEC = int(os.environ.get("GEMINI_REVIEW_TIMEOUT_SEC", "600"))
DEFAULT_API_MODEL = os.environ.get("GEMINI_REVIEW_API_MODEL", "gemini-2.5-flash")
DEBUG_LOG = Path(os.environ.get("GEMINI_REVIEW_DEBUG_LOG", f"/tmp/{SERVER_NAME}-mcp-debug.log"))
STATE_DIR = Path(
    os.environ.get(
        "GEMINI_REVIEW_STATE_DIR",
        str(Path.home() / ".codex" / "state" / SERVER_NAME),
    )
)
JOBS_DIR = STATE_DIR / "jobs"
THREADS_DIR = STATE_DIR / "threads"

_use_ndjson = False
TERMINAL_JOB_STATES = {"completed", "failed"}


def debug_log(message: str) -> None:
    try:
        DEBUG_LOG.parent.mkdir(parents=True, exist_ok=True)
        with DEBUG_LOG.open("a", encoding="utf-8") as fh:
            fh.write(f"{message}\n")
    except OSError:
        pass


def send_response(response: dict[str, Any]) -> None:
    global _use_ndjson

    payload = json.dumps(response, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    debug_log(f"SEND {payload.decode('utf-8', errors='replace')}")
    if _use_ndjson:
        sys.stdout.write(payload + b"\n")
    else:
        header = f"Content-Length: {len(payload)}\r\n\r\n".encode("utf-8")
        sys.stdout.write(header + payload)
    sys.stdout.flush()


def read_message() -> dict[str, Any] | None:
    global _use_ndjson

    line = sys.stdin.readline()
    if not line:
        return None

    line_text = line.decode("utf-8").rstrip("\r\n")
    if line_text.lower().startswith("content-length:"):
        try:
            content_length = int(line_text.split(":", 1)[1].strip())
        except ValueError:
            return None

        while True:
            header_line = sys.stdin.readline()
            if not header_line:
                return None
            if header_line in {b"\r\n", b"\n"}:
                break

        body = sys.stdin.read(content_length)
        try:
            return json.loads(body.decode("utf-8"))
        except json.JSONDecodeError:
            return None

    if line_text.startswith("{") or line_text.startswith("["):
        _use_ndjson = True
        try:
            return json.loads(line_text)
        except json.JSONDecodeError:
            return None

    return None


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp_path = path.with_suffix(path.suffix + ".tmp")
    temp_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    temp_path.replace(path)


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def load_private_env_file(env_file: Path | None = None) -> list[str]:
    target = env_file or (Path.home() / ".gemini" / ".env")
    if not target.is_file():
        return []

    loaded: list[str] = []
    for raw_line in target.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[len("export ") :].strip()
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()
        if not key:
            continue
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
            value = value[1:-1]
        if key not in os.environ:
            os.environ[key] = value
            loaded.append(key)
    return loaded


def normalize_image_paths(raw_value: Any) -> tuple[list[str], str | None]:
    if raw_value is None:
        return [], None
    if isinstance(raw_value, str):
        candidate = raw_value.strip()
        return ([candidate] if candidate else []), None
    if not isinstance(raw_value, list):
        return [], "imagePaths must be a string or an array of strings"

    image_paths: list[str] = []
    for item in raw_value:
        if not isinstance(item, str):
            return [], "imagePaths entries must be strings"
        candidate = item.strip()
        if candidate:
            image_paths.append(candidate)
    return image_paths, None


def build_inline_image_parts(image_paths: list[str]) -> tuple[list[dict[str, Any]], str | None]:
    parts: list[dict[str, Any]] = []
    for raw_path in image_paths:
        path = Path(raw_path).expanduser()
        if not path.is_file():
            return [], f"image file not found: {raw_path}"
        mime_type, _ = mimetypes.guess_type(path.name)
        if not mime_type or not mime_type.startswith("image/"):
            return [], f"unsupported image type for Gemini review: {raw_path}"
        try:
            encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        except OSError as exc:
            return [], f"failed to read image file {raw_path}: {exc}"
        parts.append({"inlineData": {"mimeType": mime_type, "data": encoded}})
    return parts, None


def find_gemini_bin() -> str | None:
    if Path(GEMINI_BIN).is_file():
        return GEMINI_BIN
    return shutil.which(GEMINI_BIN)


def resolve_backend(preferred_backend: str | None) -> str:
    backend = preferred_backend or DEFAULT_BACKEND
    if backend not in {"auto", "api", "cli"}:
        raise ValueError(f"unsupported Gemini backend: {backend}")
    if backend == "auto":
        return "api" if get_api_key() else "cli"
    return backend


def get_api_key() -> str | None:
    return os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")


def parse_gemini_json(raw_stdout: str) -> tuple[dict[str, Any] | None, str | None]:
    lines = [line.strip() for line in raw_stdout.splitlines() if line.strip()]
    if not lines:
        return None, "Gemini CLI returned empty output"

    for candidate in reversed(lines):
        try:
            payload = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(payload, dict):
            return payload, None

    return None, "Gemini CLI did not return JSON output"


def extract_cli_error_message(raw_stdout: str, raw_stderr: str) -> str:
    for text in (raw_stdout, raw_stderr):
        stripped = text.strip()
        if not stripped:
            continue
        try:
            payload = json.loads(stripped)
        except json.JSONDecodeError:
            return stripped
        if not isinstance(payload, dict):
            return stripped
        error = payload.get("error")
        if isinstance(error, dict):
            message = error.get("message")
            if isinstance(message, str) and message.strip():
                return message.strip()
        response = payload.get("response")
        if isinstance(response, str) and response.strip():
            return response.strip()
        return stripped
    return "unknown error"


def extract_api_response_text(payload: dict[str, Any]) -> str:
    candidates = payload.get("candidates")
    if isinstance(candidates, list):
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            content = candidate.get("content")
            if not isinstance(content, dict):
                continue
            parts = content.get("parts")
            if not isinstance(parts, list):
                continue
            texts: list[str] = []
            for part in parts:
                if isinstance(part, dict):
                    text = part.get("text")
                    if isinstance(text, str):
                        texts.append(text)
            if texts:
                return "\n".join(texts).strip()

    prompt_feedback = payload.get("promptFeedback")
    if isinstance(prompt_feedback, dict):
        block_reason = prompt_feedback.get("blockReason")
        if isinstance(block_reason, str) and block_reason:
            raise ValueError(f"Gemini API response blocked: {block_reason}")

    raise ValueError("Gemini API response does not contain candidate text")


def job_state_path(job_id: str) -> Path:
    return JOBS_DIR / f"{job_id}.json"


def thread_state_path(thread_id: str) -> Path:
    return THREADS_DIR / f"{thread_id}.json"


def is_pid_alive(pid: int | None) -> bool:
    if not pid or pid <= 0:
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True


def serialize_job(job: dict[str, Any]) -> dict[str, Any]:
    result = job.get("result") or {}
    return {
        "jobId": job.get("jobId"),
        "status": job.get("status"),
        "done": job.get("status") in TERMINAL_JOB_STATES,
        "threadId": result.get("threadId"),
        "response": result.get("response"),
        "model": result.get("model"),
        "backend": result.get("backend"),
        "duration_ms": result.get("duration_ms"),
        "stop_reason": result.get("stop_reason"),
        "error": job.get("error"),
        "createdAt": job.get("createdAt"),
        "startedAt": job.get("startedAt"),
        "completedAt": job.get("completedAt"),
        "updatedAt": job.get("updatedAt"),
        "resumeHint": "Call review_status with this jobId until done=true.",
    }


def load_thread_history(thread_id: str) -> list[dict[str, str]]:
    path = thread_state_path(thread_id)
    if not path.exists():
        return []
    payload = read_json(path)
    history = payload.get("history")
    if not isinstance(history, list):
        return []
    result: list[dict[str, str]] = []
    for item in history:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role", "")).strip()
        text = str(item.get("text", "")).strip()
        if role in {"user", "model"} and text:
            result.append({"role": role, "text": text})
    return result


def save_thread_history(
    *,
    thread_id: str,
    history: list[dict[str, str]],
    model: str,
    backend: str,
) -> None:
    now = utc_now()
    path = thread_state_path(thread_id)
    created_at = now
    if path.exists():
        existing = read_json(path)
        created_at = str(existing.get("createdAt") or now)
    write_json(
        path,
        {
            "threadId": thread_id,
            "createdAt": created_at,
            "updatedAt": now,
            "model": model,
            "backend": backend,
            "history": history,
        },
    )


def build_cli_prompt(
    prompt: str,
    *,
    history: list[dict[str, str]],
    system: str | None,
) -> str:
    selected_system = (system or DEFAULT_SYSTEM).strip()
    if not history and not selected_system:
        return prompt

    sections: list[str] = []
    if selected_system:
        sections.extend(["## System Instructions", selected_system, ""])
    if history:
        sections.append("## Previous Review Conversation")
        for item in history:
            role = "User" if item["role"] == "user" else "Reviewer"
            sections.append(f"### {role}")
            sections.append(item["text"])
            sections.append("")
    sections.extend(["## New User Prompt", prompt])
    return "\n".join(sections).strip()


def run_gemini_cli_review(
    prompt: str,
    *,
    history: list[dict[str, str]],
    model: str | None,
    system: str | None,
    image_paths: list[str],
) -> tuple[dict[str, Any] | None, str | None]:
    if image_paths:
        return None, "Gemini CLI backend in this bridge does not support imagePaths; use backend=api"

    bin_path = find_gemini_bin()
    if not bin_path:
        return None, f"Gemini CLI not found: {GEMINI_BIN}"

    effective_prompt = build_cli_prompt(prompt, history=history, system=system)
    cmd = [bin_path, "-p", effective_prompt, "--output-format", "json"]
    selected_model = model or DEFAULT_MODEL
    if selected_model:
        cmd.extend(["-m", selected_model])

    debug_log(f"RUN {' '.join(cmd)}")
    try:
        started = time.monotonic()
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            stdin=subprocess.DEVNULL,
            timeout=DEFAULT_TIMEOUT_SEC,
            check=False,
        )
        duration_ms = int((time.monotonic() - started) * 1000)
    except subprocess.TimeoutExpired:
        return None, f"Gemini review timed out after {DEFAULT_TIMEOUT_SEC} seconds"

    payload, parse_error = parse_gemini_json(result.stdout)
    if parse_error:
        stderr = result.stderr.strip()
        message = parse_error if not stderr else f"{parse_error}. stderr: {stderr}"
        return None, message

    assert payload is not None
    if result.returncode != 0:
        return None, f"Gemini review failed: {extract_cli_error_message(result.stdout, result.stderr)}"

    response_text = str(payload.get("response", "")).strip()
    if not response_text:
        return None, "Gemini CLI JSON payload does not contain a non-empty response field"

    return {
        "response": response_text,
        "model": payload.get("model", "") or selected_model or "gemini-cli",
        "duration_ms": duration_ms,
        "stop_reason": payload.get("stop_reason"),
        "backend": "cli",
    }, None


def run_gemini_api_review(
    prompt: str,
    *,
    history: list[dict[str, str]],
    model: str | None,
    system: str | None,
    image_paths: list[str],
) -> tuple[dict[str, Any] | None, str | None]:
    api_key = get_api_key()
    if not api_key:
        return None, "Gemini API backend requires GEMINI_API_KEY or GOOGLE_API_KEY"

    selected_model = model or DEFAULT_MODEL or DEFAULT_API_MODEL
    request_payload: dict[str, Any] = {
        "contents": [],
        "generationConfig": {"temperature": 0.2},
    }
    selected_system = (system or DEFAULT_SYSTEM).strip()
    if selected_system:
        request_payload["systemInstruction"] = {"parts": [{"text": selected_system}]}
    for item in history:
        request_payload["contents"].append(
            {
                "role": item["role"],
                "parts": [{"text": item["text"]}],
            }
        )
    user_parts: list[dict[str, Any]] = [{"text": prompt}]
    inline_parts, image_error = build_inline_image_parts(image_paths)
    if image_error:
        return None, image_error
    user_parts.extend(inline_parts)
    request_payload["contents"].append({"role": "user", "parts": user_parts})

    url = f"https://generativelanguage.googleapis.com/v1beta/models/{selected_model}:generateContent"
    request = urllib.request.Request(
        url,
        data=json.dumps(request_payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "x-goog-api-key": api_key,
        },
        method="POST",
    )

    debug_log(f"RUN gemini-api {selected_model}")
    try:
        started = time.monotonic()
        with urllib.request.urlopen(request, timeout=DEFAULT_TIMEOUT_SEC) as response:
            raw_stdout = response.read().decode("utf-8")
        duration_ms = int((time.monotonic() - started) * 1000)
    except urllib.error.HTTPError as exc:
        raw_text = exc.read().decode("utf-8", errors="replace")
        message = raw_text.strip()
        try:
            error_payload = json.loads(raw_text)
            if isinstance(error_payload, dict):
                error = error_payload.get("error")
                if isinstance(error, dict):
                    api_message = error.get("message")
                    if isinstance(api_message, str) and api_message.strip():
                        message = api_message.strip()
        except json.JSONDecodeError:
            pass
        return None, f"Gemini API failed with HTTP {exc.code}: {message or 'unknown error'}"
    except urllib.error.URLError as exc:
        return None, f"Gemini API request failed: {exc.reason}"

    try:
        api_payload = json.loads(raw_stdout)
    except json.JSONDecodeError:
        return None, "Gemini API response is not valid JSON"
    if not isinstance(api_payload, dict):
        return None, "Gemini API response JSON must be an object"

    try:
        response_text = extract_api_response_text(api_payload)
    except ValueError as exc:
        return None, str(exc)

    return {
        "response": response_text,
        "model": selected_model,
        "duration_ms": duration_ms,
        "stop_reason": None,
        "backend": "api",
    }, None


def run_gemini_review(
    prompt: str,
    *,
    session_id: str | None = None,
    model: str | None = None,
    system: str | None = None,
    tools: str | None = None,
    backend: str | None = None,
    image_paths: Any = None,
) -> tuple[dict[str, Any] | None, str | None]:
    del tools

    load_private_env_file()

    normalized_image_paths, image_error = normalize_image_paths(image_paths)
    if image_error:
        return None, image_error

    thread_id = session_id or uuid.uuid4().hex
    history = load_thread_history(thread_id) if session_id else []
    try:
        selected_backend = resolve_backend(backend)
    except ValueError as exc:
        return None, str(exc)

    if selected_backend == "api":
        payload, error = run_gemini_api_review(
            prompt,
            history=history,
            model=model,
            system=system,
            image_paths=normalized_image_paths,
        )
    else:
        payload, error = run_gemini_cli_review(
            prompt,
            history=history,
            model=model,
            system=system,
            image_paths=normalized_image_paths,
        )
    if error:
        return None, error

    assert payload is not None
    updated_history = list(history)
    updated_history.append({"role": "user", "text": prompt})
    updated_history.append({"role": "model", "text": str(payload["response"])})
    save_thread_history(
        thread_id=thread_id,
        history=updated_history,
        model=str(payload["model"]),
        backend=str(payload["backend"]),
    )
    payload["threadId"] = thread_id
    return payload, None


def start_async_review(
    prompt: str,
    *,
    session_id: str | None = None,
    model: str | None = None,
    system: str | None = None,
    tools: str | None = None,
    backend: str | None = None,
    image_paths: Any = None,
) -> tuple[dict[str, Any] | None, str | None]:
    normalized_image_paths, image_error = normalize_image_paths(image_paths)
    if image_error:
        return None, image_error

    job_id = uuid.uuid4().hex
    created_at = utc_now()
    job = {
        "jobId": job_id,
        "status": "queued",
        "createdAt": created_at,
        "startedAt": None,
        "completedAt": None,
        "updatedAt": created_at,
        "error": None,
        "result": None,
        "workerPid": None,
        "request": {
            "prompt": prompt,
            "threadId": session_id,
            "model": model,
            "system": system,
            "tools": tools,
            "backend": backend,
            "imagePaths": normalized_image_paths,
        },
    }

    job_path = job_state_path(job_id)
    write_json(job_path, job)

    try:
        worker = subprocess.Popen(
            [sys.executable, str(Path(__file__).resolve()), "--run-job", job_id],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            close_fds=True,
            start_new_session=True,
        )
    except OSError as exc:
        job["status"] = "failed"
        job["completedAt"] = utc_now()
        job["updatedAt"] = job["completedAt"]
        job["error"] = f"Failed to launch background review worker: {exc}"
        write_json(job_path, job)
        return None, job["error"]

    job["workerPid"] = worker.pid
    job["updatedAt"] = utc_now()
    write_json(job_path, job)
    debug_log(f"JOB_START job_id={job_id} worker_pid={worker.pid}")
    return serialize_job(job), None


def get_review_status(job_id: str, *, wait_seconds: int = 0) -> tuple[dict[str, Any] | None, str | None]:
    job_path = job_state_path(job_id)
    if not job_path.exists():
        return None, f"Unknown jobId: {job_id}"

    deadline = time.monotonic() + max(wait_seconds, 0)
    while True:
        job = read_json(job_path)
        if job.get("status") in {"queued", "running"} and not is_pid_alive(job.get("workerPid")):
            job["status"] = "failed"
            job["error"] = "Background review worker exited before writing a final result"
            job["completedAt"] = utc_now()
            job["updatedAt"] = job["completedAt"]
            write_json(job_path, job)
        if job.get("status") in TERMINAL_JOB_STATES:
            return serialize_job(job), None
        if time.monotonic() >= deadline:
            return serialize_job(job), None
        time.sleep(min(0.5, max(deadline - time.monotonic(), 0.0)))


def run_async_job(job_id: str) -> int:
    job_path = job_state_path(job_id)
    if not job_path.exists():
        debug_log(f"JOB_MISSING job_id={job_id}")
        return 1

    job = read_json(job_path)
    job["status"] = "running"
    job["startedAt"] = utc_now()
    job["updatedAt"] = job["startedAt"]
    job["workerPid"] = os.getpid()
    write_json(job_path, job)
    debug_log(f"JOB_RUNNING job_id={job_id} worker_pid={os.getpid()}")

    request = job.get("request") or {}
    try:
        payload, error = run_gemini_review(
            str(request.get("prompt", "")),
            session_id=request.get("threadId"),
            model=request.get("model"),
            system=request.get("system"),
            tools=request.get("tools"),
            backend=request.get("backend"),
            image_paths=request.get("imagePaths"),
        )
    except Exception as exc:
        payload = None
        error = f"Background review crashed: {exc}"
        debug_log(traceback.format_exc())

    finished_at = utc_now()
    job = read_json(job_path)
    job["updatedAt"] = finished_at
    job["completedAt"] = finished_at
    if error:
        job["status"] = "failed"
        job["error"] = error
        job["result"] = None
        debug_log(f"JOB_FAILED job_id={job_id} error={error}")
        write_json(job_path, job)
        return 1

    job["status"] = "completed"
    job["error"] = None
    job["result"] = payload
    debug_log(f"JOB_COMPLETED job_id={job_id} thread_id={(payload or {}).get('threadId')}")
    write_json(job_path, job)
    return 0


def tool_success(request_id: Any, payload: dict[str, Any]) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "result": {
            "content": [{"type": "text", "text": json.dumps(payload, ensure_ascii=False)}],
        },
    }


def tool_error(request_id: Any, message: str) -> dict[str, Any]:
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "result": {
            "content": [{"type": "text", "text": json.dumps({"error": message}, ensure_ascii=False)}],
            "isError": True,
        },
    }


def handle_request(request: dict[str, Any]) -> dict[str, Any] | None:
    request_id = request.get("id")
    method = request.get("method", "")
    params = request.get("params", {})
    debug_log(f"REQUEST id={request_id!r} method={method} params={json.dumps(params, ensure_ascii=False)}")

    if request_id is None:
        if method in {"notifications/initialized", "initialized"}:
            return None
        return None

    if method == "initialize":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "protocolVersion": "2024-11-05",
                "capabilities": {"tools": {}},
                "serverInfo": {"name": SERVER_NAME, "version": "1.0.0"},
            },
        }

    if method == "ping":
        return {"jsonrpc": "2.0", "id": request_id, "result": {}}

    if method == "resources/list":
        return {"jsonrpc": "2.0", "id": request_id, "result": {"resources": []}}

    if method == "resources/templates/list":
        return {"jsonrpc": "2.0", "id": request_id, "result": {"resourceTemplates": []}}

    if method in {"notifications/initialized", "initialized"}:
        return {"jsonrpc": "2.0", "id": request_id, "result": {}}

    if method == "tools/list":
        common_properties = {
            "prompt": {"type": "string", "description": "Reviewer prompt"},
            "system": {"type": "string", "description": "Optional system prompt"},
            "model": {"type": "string", "description": "Optional Gemini model override"},
            "backend": {"type": "string", "description": "Optional Gemini backend override: auto, api, or cli"},
            "tools": {"type": "string", "description": "Accepted for compatibility but ignored by Gemini review"},
            "imagePaths": {
                "type": "array",
                "items": {"type": "string"},
                "description": "Optional local image paths for Gemini API multimodal review",
            },
            "image_paths": {
                "type": "array",
                "items": {"type": "string"},
                "description": "Alias of imagePaths",
            },
        }
        reply_properties = {
            "threadId": {"type": "string", "description": "Gemini thread id from a previous review call"},
            "thread_id": {"type": "string", "description": "Alias of threadId"},
            **common_properties,
        }
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "tools": [
                    {
                        "name": "review",
                        "description": "Run a fresh Gemini review and return JSON containing threadId and response.",
                        "inputSchema": {
                            "type": "object",
                            "properties": common_properties,
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_reply",
                        "description": "Continue a previous Gemini review session using threadId.",
                        "inputSchema": {
                            "type": "object",
                            "properties": reply_properties,
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_start",
                        "description": "Start a background Gemini review job and return a resumable jobId immediately.",
                        "inputSchema": {
                            "type": "object",
                            "properties": common_properties,
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_reply_start",
                        "description": "Start a background follow-up review job in an existing Gemini thread and return a resumable jobId immediately.",
                        "inputSchema": {
                            "type": "object",
                            "properties": reply_properties,
                            "required": ["prompt"],
                        },
                    },
                    {
                        "name": "review_status",
                        "description": "Check whether a background review job has finished and fetch the final result when available.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "jobId": {"type": "string", "description": "Background review job id"},
                                "job_id": {"type": "string", "description": "Alias of jobId"},
                                "waitSeconds": {"type": "integer", "description": "Optional bounded wait before returning status"},
                            },
                            "required": ["jobId"],
                        },
                    },
                ]
            },
        }

    if method == "tools/call":
        name = params.get("name", "")
        args = params.get("arguments", {}) or {}

        if name == "review":
            payload, error = run_gemini_review(
                str(args.get("prompt", "")),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
                backend=args.get("backend"),
                image_paths=args.get("imagePaths") or args.get("image_paths"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_reply":
            thread_id = args.get("threadId") or args.get("thread_id")
            if not thread_id:
                return tool_error(request_id, "threadId or thread_id is required")
            payload, error = run_gemini_review(
                str(args.get("prompt", "")),
                session_id=str(thread_id),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
                backend=args.get("backend"),
                image_paths=args.get("imagePaths") or args.get("image_paths"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_start":
            payload, error = start_async_review(
                str(args.get("prompt", "")),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
                backend=args.get("backend"),
                image_paths=args.get("imagePaths") or args.get("image_paths"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_reply_start":
            thread_id = args.get("threadId") or args.get("thread_id")
            if not thread_id:
                return tool_error(request_id, "threadId or thread_id is required")
            payload, error = start_async_review(
                str(args.get("prompt", "")),
                session_id=str(thread_id),
                model=args.get("model"),
                system=args.get("system"),
                tools=args.get("tools"),
                backend=args.get("backend"),
                image_paths=args.get("imagePaths") or args.get("image_paths"),
            )
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        if name == "review_status":
            job_id = args.get("jobId") or args.get("job_id")
            if not job_id:
                return tool_error(request_id, "jobId or job_id is required")
            wait_seconds_raw = args.get("waitSeconds", 0)
            try:
                wait_seconds = int(wait_seconds_raw)
            except (TypeError, ValueError):
                return tool_error(request_id, "waitSeconds must be an integer")
            payload, error = get_review_status(str(job_id), wait_seconds=max(wait_seconds, 0))
            return tool_error(request_id, error) if error else tool_success(request_id, payload or {})

        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "error": {"code": -32601, "message": f"Unknown tool: {name}"},
        }

    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "error": {"code": -32601, "message": f"Unknown method: {method}"},
    }


def main() -> None:
    if len(sys.argv) == 3 and sys.argv[1] == "--run-job":
        raise SystemExit(run_async_job(sys.argv[2]))

    debug_log(f"=== {SERVER_NAME} starting ===")
    while True:
        try:
            request = read_message()
            if request is None:
                debug_log("EOF")
                break
            response = handle_request(request)
            if response is not None:
                send_response(response)
        except Exception:
            debug_log(traceback.format_exc())
            break


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""MiniMax Chat MCP Server - A robust MCP server that calls MiniMax Chat Completions API"""

import json
import os
import sys
import tempfile
import httpx

# Force unbuffered stdout/stdin
sys.stdout = os.fdopen(sys.stdout.fileno(), 'wb', buffering=0)
sys.stdin = os.fdopen(sys.stdin.fileno(), 'rb', buffering=0)

# Debug logging
DEBUG_LOG = os.path.join(tempfile.gettempdir(), "minimax-mcp-debug.log")

def debug_log(msg):
    """Write debug message to log file"""
    try:
        with open(DEBUG_LOG, "a") as f:
            import datetime
            f.write(f"{datetime.datetime.now()}: {msg}\n")
            f.flush()
    except:
        pass

debug_log("=== MCP Server Starting (v2.1) ===")
debug_log(f"MINIMAX_API_KEY set: {bool(os.environ.get('MINIMAX_API_KEY'))}")
debug_log(f"MINIMAX_BASE_URL: {os.environ.get('MINIMAX_BASE_URL', 'not set')}")
debug_log(f"MINIMAX_MODEL: {os.environ.get('MINIMAX_MODEL', 'not set')}")

MINIMAX_API_KEY = os.environ.get("MINIMAX_API_KEY", "")
MINIMAX_BASE_URL = os.environ.get("MINIMAX_BASE_URL", "https://api.minimax.io/v1")
DEFAULT_MODEL = os.environ.get("MINIMAX_MODEL", "MiniMax-M2.7")

# MiniMax requires temperature in (0.0, 1.0]
def clamp_temperature(temp):
    """Clamp temperature to MiniMax's allowed range (0.0, 1.0]."""
    if temp is None:
        return None
    temp = float(temp)
    if temp <= 0.0:
        return 0.01
    if temp > 1.0:
        return 1.0
    return temp

def log_error(msg):
    try:
        with open(DEBUG_LOG, "a") as f:
            import datetime
            f.write(f"{datetime.datetime.now()}: ERROR: {msg}\n")
    except:
        pass

# Global flag for output format
_use_ndjson = False

def send_response(response):
    """Send a JSON-RPC response using binary stdout"""
    global _use_ndjson
    json_str = json.dumps(response, separators=(',', ':'))
    json_bytes = json_str.encode('utf-8')

    if _use_ndjson:
        # NDJSON format: just the JSON followed by newline
        output = json_bytes + b'\n'
    else:
        # Standard MCP format: Content-Length header + body
        header = f"Content-Length: {len(json_bytes)}\r\n\r\n".encode('utf-8')
        output = header + json_bytes

    sys.stdout.write(output)
    sys.stdout.flush()
    debug_log(f"Sent response ({'NDJSON' if _use_ndjson else 'MCP'}): {json_str[:200]}...")

def send_notification(method, params=None):
    """Send a JSON-RPC notification"""
    notification = {
        "jsonrpc": "2.0",
        "method": method
    }
    if params:
        notification["params"] = params
    send_response(notification)

def call_minimax(messages, model=None, temperature=0.7):
    """Call MiniMax Chat Completions API"""
    if not MINIMAX_API_KEY:
        return None, "MINIMAX_API_KEY environment variable not set"

    url = f"{MINIMAX_BASE_URL}/chat/completions"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {MINIMAX_API_KEY}"
    }
    clamped_temp = clamp_temperature(temperature)
    payload = {
        "model": model or DEFAULT_MODEL,
        "messages": messages,
        "max_tokens": 4096,
        "temperature": clamped_temp
    }

    debug_log(f"Calling MiniMax API: {url}")

    try:
        with httpx.Client(timeout=120.0) as client:
            response = client.post(url, headers=headers, json=payload)
            if response.status_code != 200:
                error_msg = f"API error {response.status_code}: {response.text[:500]}"
                debug_log(f"API error: {error_msg}")
                return None, error_msg
            data = response.json()
            content = data["choices"][0]["message"]["content"]
            debug_log(f"API success, response length: {len(content)}")
            return content, None
    except Exception as e:
        debug_log(f"API exception: {str(e)}")
        return None, str(e)

def handle_request(request):
    """Handle a JSON-RPC request"""
    method = request.get("method", "")
    params = request.get("params", {})
    request_id = request.get("id")

    debug_log(f"Handling method: {method}, id: {request_id}")

    # Handle notifications (no id, no response needed)
    if request_id is None:
        debug_log(f"Notification received: {method}")
        if method == "notifications/initialized":
            debug_log("Client initialized successfully")
        return None

    if method == "initialize":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "protocolVersion": "2024-11-05",
                "capabilities": {
                    "tools": {}
                },
                "serverInfo": {
                    "name": "minimax-chat",
                    "version": "2.0.0"
                }
            }
        }

    elif method == "ping":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {}
        }

    elif method == "tools/list":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "tools": [{
                    "name": "minimax_chat",
                    "description": "Send a message to MiniMax model and get a response. Use this for research reviews, code analysis, and general AI tasks. Supports MiniMax-M2.7 (default, 204K context) and MiniMax-M2.7-highspeed.",
                    "inputSchema": {
                        "type": "object",
                        "properties": {
                            "prompt": {
                                "type": "string",
                                "description": "The prompt to send to MiniMax"
                            },
                            "model": {
                                "type": "string",
                                "description": "Model to use: MiniMax-M2.7 (default, 204K context) or MiniMax-M2.7-highspeed (faster, 204K context)",
                                "default": "MiniMax-M2.7",
                                "enum": ["MiniMax-M2.7", "MiniMax-M2.7-highspeed", "MiniMax-M2.5", "MiniMax-M2.5-highspeed"]
                            },
                            "system": {
                                "type": "string",
                                "description": "Optional system prompt"
                            },
                            "temperature": {
                                "type": "number",
                                "description": "Sampling temperature (0.01-1.0). Default: 0.7",
                                "default": 0.7
                            }
                        },
                        "required": ["prompt"]
                    }
                }]
            }
        }

    elif method == "tools/call":
        tool_name = params.get("name", "")
        arguments = params.get("arguments", {})

        if tool_name == "minimax_chat":
            prompt = arguments.get("prompt", "")
            model = arguments.get("model", DEFAULT_MODEL)
            system = arguments.get("system", "")
            temperature = arguments.get("temperature", 0.7)

            messages = []
            if system:
                messages.append({"role": "system", "content": system})
            messages.append({"role": "user", "content": prompt})

            debug_log(f"Tool call: minimax_chat, prompt length: {len(prompt)}")
            content, error = call_minimax(messages, model, temperature)

            if error:
                return {
                    "jsonrpc": "2.0",
                    "id": request_id,
                    "result": {
                        "content": [{"type": "text", "text": f"Error: {error}"}],
                        "isError": True
                    }
                }

            return {
                "jsonrpc": "2.0",
                "id": request_id,
                "result": {
                    "content": [{"type": "text", "text": content}]
                }
            }

        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "error": {"code": -32601, "message": f"Unknown tool: {tool_name}"}
        }

    else:
        debug_log(f"Unknown method: {method}")
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "error": {"code": -32601, "message": f"Unknown method: {method}"}
        }

def read_message():
    """Read a single JSON-RPC message from stdin. Returns None on EOF.

    Supports two formats:
    1. Standard MCP: Content-Length: N\\r\\n\\r\\n{json}
    2. NDJSON/Line-delimited: {json}\\n
    """
    content_length = None
    first_line = None

    # Read first line to determine format
    line = sys.stdin.readline()
    if not line:  # EOF
        return None

    line = line.decode('utf-8').rstrip('\r\n')
    debug_log(f"First line: '{line[:100]}...'")

    # Check if it's a Content-Length header or direct JSON
    if line.lower().startswith("content-length:"):
        # Standard MCP format
        try:
            content_length = int(line.split(":", 1)[1].strip())
            debug_log(f"Content-Length: {content_length}")
        except ValueError:
            log_error(f"Invalid Content-Length: {line}")
            return None

        # Read remaining headers until blank line
        while True:
            hdr = sys.stdin.readline()
            if not hdr:
                return None
            hdr = hdr.decode('utf-8').rstrip('\r\n')
            if hdr == "":
                break
            debug_log(f"Header: '{hdr}'")

    elif line.startswith("{") or line.startswith("["):
        # NDJSON format - the line IS the JSON
        global _use_ndjson
        _use_ndjson = True
        debug_log("Detected NDJSON format (line-delimited JSON)")
        try:
            request = json.loads(line)
            debug_log(f"Parsed NDJSON request: {json.dumps(request)[:200]}")
            return request
        except json.JSONDecodeError as e:
            log_error(f"JSON decode error in NDJSON: {e}")
            return None

    else:
        log_error(f"Unexpected line format: {line[:100]}")
        return None

    if content_length is None:
        log_error("Missing Content-Length header")
        return None

    # Read the body (for standard MCP format)
    body = sys.stdin.read(content_length)
    if len(body) < content_length:
        log_error(f"Incomplete body: expected {content_length}, got {len(body)}")
        return None

    try:
        request = json.loads(body.decode('utf-8'))
        debug_log(f"Parsed request: {json.dumps(request)[:200]}")
        return request
    except json.JSONDecodeError as e:
        log_error(f"JSON decode error: {e}")
        return None

def main():
    """Main loop - read JSON-RPC messages from stdin"""
    debug_log("Entering main loop")

    while True:
        try:
            request = read_message()
            if request is None:
                debug_log("Received EOF, exiting gracefully")
                break

            debug_log(f"Processing: {request.get('method', 'unknown')}")

            response = handle_request(request)
            if response:
                send_response(response)

        except Exception as e:
            log_error(f"Exception in main loop: {e}")
            debug_log(f"Exception: {e}")
            # Try to send error response
            try:
                send_response({
                    "jsonrpc": "2.0",
                    "id": None,
                    "error": {"code": -32603, "message": f"Internal error: {e}"}
                })
            except:
                pass

    debug_log("=== MCP Server Exiting ===")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Feishu Bridge Server — provides HTTP API for ARIS skills to send messages
to Feishu and poll for user replies.

Endpoints:
  POST /send   — send a card message to Feishu user, return message_id
  GET  /poll    — wait for user reply (long-poll with timeout)
  GET  /health  — health check

Requires:
  pip install lark-oapi httpx

Environment variables:
  FEISHU_APP_ID      — Feishu app ID
  FEISHU_APP_SECRET  — Feishu app secret
  FEISHU_USER_ID     — Target user's open_id (who receives notifications)
  BRIDGE_PORT        — HTTP port (default: 5000)
"""

import os
import sys
import json
import time
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler

try:
    import lark_oapi as lark
    from lark_oapi.api.im.v1 import (
        CreateMessageRequest, CreateMessageRequestBody,
    )
except ImportError:
    print("Error: lark-oapi not installed. Run: pip install lark-oapi", file=sys.stderr)
    sys.exit(1)

# --- Configuration ---
APP_ID = os.environ.get("FEISHU_APP_ID", "")
APP_SECRET = os.environ.get("FEISHU_APP_SECRET", "")
USER_ID = os.environ.get("FEISHU_USER_ID", "")
PORT = int(os.environ.get("BRIDGE_PORT", "5000"))

if not APP_ID or not APP_SECRET:
    print("Error: FEISHU_APP_ID and FEISHU_APP_SECRET are required", file=sys.stderr)
    sys.exit(1)

if not USER_ID:
    print("Warning: FEISHU_USER_ID not set — /send will require user_id in request body", file=sys.stderr)

# --- Lark Client ---
client = lark.Client.builder().app_id(APP_ID).app_secret(APP_SECRET).build()

# --- Reply Store (thread-safe) ---
reply_store = {}
reply_lock = threading.Lock()
reply_events = {}


def send_card(user_id: str, title: str, body: str, color: str = "blue") -> dict:
    """Send an interactive card to a Feishu user."""
    card = json.dumps({
        "header": {
            "title": {"tag": "plain_text", "content": title},
            "template": color,
        },
        "elements": [
            {"tag": "markdown", "content": body}
        ]
    })

    request = CreateMessageRequest.builder() \
        .receive_id_type("open_id") \
        .request_body(
            CreateMessageRequestBody.builder()
            .receive_id(user_id)
            .msg_type("interactive")
            .content(card)
            .build()
        ).build()

    response = client.im.v1.message.create(request)

    if not response.success():
        return {"error": response.msg, "code": response.code}

    msg_id = response.data.message_id
    # Prepare reply event for this message
    with reply_lock:
        reply_events[msg_id] = threading.Event()
        reply_store[msg_id] = None

    return {"ok": True, "message_id": msg_id}


def send_text(user_id: str, text: str) -> dict:
    """Send a plain text message to a Feishu user."""
    request = CreateMessageRequest.builder() \
        .receive_id_type("open_id") \
        .request_body(
            CreateMessageRequestBody.builder()
            .receive_id(user_id)
            .msg_type("text")
            .content(json.dumps({"text": text}))
            .build()
        ).build()

    response = client.im.v1.message.create(request)

    if not response.success():
        return {"error": response.msg, "code": response.code}

    return {"ok": True, "message_id": response.data.message_id}


def poll_reply(message_id: str, timeout: int = 300) -> dict:
    """Wait for a user reply to a specific message."""
    with reply_lock:
        event = reply_events.get(message_id)

    if not event:
        return {"error": "unknown message_id"}

    # Wait for reply or timeout
    got_reply = event.wait(timeout=timeout)

    with reply_lock:
        reply = reply_store.pop(message_id, None)
        reply_events.pop(message_id, None)

    if got_reply and reply:
        return {"reply": reply}
    else:
        return {"timeout": True}


def receive_reply(message_id: str, text: str):
    """Called when a user replies (webhook or external trigger)."""
    with reply_lock:
        if message_id in reply_store:
            reply_store[message_id] = text
            reply_events[message_id].set()


# --- HTTP Handler ---
class BridgeHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/health":
            self._json_response({"status": "ok", "port": PORT})
            return

        if self.path.startswith("/poll"):
            # Parse query params
            params = {}
            if "?" in self.path:
                query = self.path.split("?", 1)[1]
                for pair in query.split("&"):
                    if "=" in pair:
                        k, v = pair.split("=", 1)
                        params[k] = v

            message_id = params.get("message_id", "")
            timeout = int(params.get("timeout", "300"))

            if not message_id:
                self._json_response({"error": "message_id required"}, 400)
                return

            result = poll_reply(message_id, timeout)
            self._json_response(result)
            return

        self._json_response({"error": "not found"}, 404)

    def do_POST(self):
        if self.path == "/send":
            content_length = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(content_length)) if content_length else {}

            user_id = body.get("user_id", USER_ID)
            if not user_id:
                self._json_response({"error": "user_id required (set FEISHU_USER_ID or pass in body)"}, 400)
                return

            msg_type = body.get("type", "card")
            title = body.get("title", "ARIS Notification")
            content = body.get("body", body.get("content", ""))
            color = body.get("color", "blue")

            if msg_type == "text":
                result = send_text(user_id, content)
            else:
                result = send_card(user_id, title, content, color)

            self._json_response(result)
            return

        if self.path == "/reply":
            # External hook: when user replies, call this endpoint
            content_length = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(content_length)) if content_length else {}

            message_id = body.get("message_id", "")
            text = body.get("text", "")

            if message_id:
                receive_reply(message_id, text)
                self._json_response({"ok": True})
            else:
                self._json_response({"error": "message_id required"}, 400)
            return

        self._json_response({"error": "not found"}, 404)

    def _json_response(self, data, status=200):
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def log_message(self, format, *args):
        # Quiet logging
        pass


def main():
    server = HTTPServer(("0.0.0.0", PORT), BridgeHandler)
    print(f"Feishu Bridge Server running on http://0.0.0.0:{PORT}")
    print(f"  POST /send   — send card/text to Feishu")
    print(f"  GET  /poll   — wait for user reply")
    print(f"  POST /reply  — receive user reply (webhook)")
    print(f"  GET  /health — health check")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down.")
        server.server_close()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Generic LLM Chat MCP Server - Supports any OpenAI-compatible API

Environment Variables:
    LLM_API_KEY      - API key (required)
    LLM_BASE_URL     - API base URL (default: https://api.openai.com/v1)
    LLM_MODEL        - Model name (default: gpt-4o)
    LLM_SERVER_NAME  - Server name for MCP (default: llm-chat)

Supported Providers (examples):
    OpenAI:      LLM_BASE_URL=https://api.openai.com/v1 LLM_MODEL=gpt-4o
    DeepSeek:    LLM_BASE_URL=https://api.deepseek.com/v1 LLM_MODEL=deepseek-chat
    Kimi:        LLM_BASE_URL=https://api.moonshot.cn/v1 LLM_MODEL=moonshot-v1-32k
    MiniMax:     LLM_BASE_URL=https://api.minimax.io/v1 LLM_MODEL=MiniMax-M2.7
"""

import json
import os
import sys
import tempfile
import httpx

# Force unbuffered stdout/stdin
sys.stdout = os.fdopen(sys.stdout.fileno(), 'wb', buffering=0)
sys.stdin = os.fdopen(sys.stdin.fileno(), 'rb', buffering=0)

# Configuration from environment
API_KEY = os.environ.get("LLM_API_KEY", "")
BASE_URL = os.environ.get("LLM_BASE_URL", "https://api.openai.com/v1")
DEFAULT_MODEL = os.environ.get("LLM_MODEL", "gpt-4o")
SERVER_NAME = os.environ.get("LLM_SERVER_NAME", "llm-chat")

# Debug logging
DEBUG_LOG = os.path.join(tempfile.gettempdir(), f"{SERVER_NAME}-mcp-debug.log")

def debug_log(msg):
    try:
        with open(DEBUG_LOG, "a") as f:
            import datetime
            f.write(f"{datetime.datetime.now()}: {msg}\n")
            f.flush()
    except:
        pass

def log_error(msg):
    try:
        with open(DEBUG_LOG, "a") as f:
            import datetime
            f.write(f"{datetime.datetime.now()}: ERROR: {msg}\n")
    except:
        pass

debug_log(f"=== {SERVER_NAME} MCP Server Starting (v2.0) ===")
debug_log(f"BASE_URL: {BASE_URL}")
debug_log(f"MODEL: {DEFAULT_MODEL}")
debug_log(f"API_KEY set: {bool(API_KEY)}")

_use_ndjson = False

def send_response(response):
    global _use_ndjson
    json_str = json.dumps(response, separators=(',', ':'))
    json_bytes = json_str.encode('utf-8')

    if _use_ndjson:
        output = json_bytes + b'\n'
    else:
        header = f"Content-Length: {len(json_bytes)}\r\n\r\n".encode('utf-8')
        output = header + json_bytes

    sys.stdout.write(output)
    sys.stdout.flush()

def call_llm(messages, model=None):
    """Call LLM Chat Completions API"""
    if not API_KEY:
        return None, "LLM_API_KEY environment variable not set"

    url = f"{BASE_URL.rstrip('/')}/chat/completions"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {API_KEY}"
    }
    payload = {
        "model": model or DEFAULT_MODEL,
        "messages": messages,
        "max_tokens": 4096
    }

    debug_log(f"Calling LLM API: {url}")

    try:
        with httpx.Client(timeout=300.0) as client:
            response = client.post(url, headers=headers, json=payload)
            if response.status_code != 200:
                error_msg = f"API error {response.status_code}: {response.text[:500]}"
                debug_log(f"API error: {error_msg}")
                return None, error_msg
            data = response.json()
            content = data["choices"][0]["message"]["content"]
            debug_log(f"API success, response length: {len(content)}")
            return content, None
    except Exception as e:
        debug_log(f"API exception: {str(e)}")
        return None, str(e)

def handle_request(request):
    """Handle a JSON-RPC request"""
    method = request.get("method", "")
    params = request.get("params", {})
    request_id = request.get("id")

    debug_log(f"Handling method: {method}, id: {request_id}")

    # Handle notifications (no id, no response needed)
    if request_id is None:
        if method == "notifications/initialized":
            debug_log("Client initialized successfully")
        return None

    if method == "initialize":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "protocolVersion": "2024-11-05",
                "capabilities": {
                    "tools": {}
                },
                "serverInfo": {
                    "name": SERVER_NAME,
                    "version": "2.0.0"
                }
            }
        }

    elif method == "ping":
        return {"jsonrpc": "2.0", "id": request_id, "result": {}}

    elif method == "tools/list":
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "result": {
                "tools": [{
                    "name": "chat",
                    "description": f"Send a message to {DEFAULT_MODEL} and get a response. Use this for research reviews, code analysis, and general AI tasks.",
                    "inputSchema": {
                        "type": "object",
                        "properties": {
                            "prompt": {
                                "type": "string",
                                "description": "The prompt to send"
                            },
                            "model": {
                                "type": "string",
                                "description": f"Model to use (default: {DEFAULT_MODEL})"
                            },
                            "system": {
                                "type": "string",
                                "description": "Optional system prompt"
                            }
                        },
                        "required": ["prompt"]
                    }
                }]
            }
        }

    elif method == "tools/call":
        tool_name = params.get("name", "")
        arguments = params.get("arguments", {})

        if tool_name == "chat":
            prompt = arguments.get("prompt", "")
            model = arguments.get("model", DEFAULT_MODEL)
            system = arguments.get("system", "")

            messages = []
            if system:
                messages.append({"role": "system", "content": system})
            messages.append({"role": "user", "content": prompt})

            debug_log(f"Tool call: chat, prompt length: {len(prompt)}")
            content, error = call_llm(messages, model)

            if error:
                return {
                    "jsonrpc": "2.0",
                    "id": request_id,
                    "result": {
                        "content": [{"type": "text", "text": f"Error: {error}"}],
                        "isError": True
                    }
                }

            return {
                "jsonrpc": "2.0",
                "id": request_id,
                "result": {
                    "content": [{"type": "text", "text": content}]
                }
            }

        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "error": {"code": -32601, "message": f"Unknown tool: {tool_name}"}
        }

    else:
        return {
            "jsonrpc": "2.0",
            "id": request_id,
            "error": {"code": -32601, "message": f"Unknown method: {method}"}
        }

def read_message():
    """Read a single JSON-RPC message from stdin."""
    global _use_ndjson

    line = sys.stdin.readline()
    if not line:
        return None

    line = line.decode('utf-8').rstrip('\r\n')

    if line.lower().startswith("content-length:"):
        try:
            content_length = int(line.split(":", 1)[1].strip())
        except ValueError:
            return None

        while True:
            hdr = sys.stdin.readline()
            if not hdr:
                return None
            hdr = hdr.decode('utf-8').rstrip('\r\n')
            if hdr == "":
                break

        body = sys.stdin.read(content_length)
        try:
            return json.loads(body.decode('utf-8'))
        except:
            return None

    elif line.startswith("{") or line.startswith("["):
        _use_ndjson = True
        try:
            return json.loads(line)
        except:
            return None

    return None

def main():
    """Main loop - read JSON-RPC messages from stdin"""
    debug_log("Entering main loop")

    while True:
        try:
            request = read_message()
            if request is None:
                debug_log("EOF, exiting")
                break

            response = handle_request(request)
            if response:
                send_response(response)

        except Exception as e:
            log_error(f"Exception: {e}")

    debug_log("=== Server Exiting ===")

if __name__ == "__main__":
    main()

